        string? channel = this.safeString(message, "channel");
        List<object> events = this.safeList(message, "events", new List<object>() {});
        string? datetime = this.safeString(message, "timestamp");
        Int64? timestamp = this.parse8601(datetime);
        List<object> newTickers = new List<object>() {};
        for (int i = 0; i < events.Count; i++)
        {
            IDictionary<string, object> tickersObj = this.safeDict(events, i);
            List<object> tickers = this.safeList(tickersObj, "tickers", new List<object>() {});
            for (int j = 0; j < tickers.Count; j++)
            {
                object ticker = tickers[j];
                string? wsMarketId = this.safeString(ticker, "product_id");
                if ((wsMarketId == null))
                {
                    continue;
                }
                Dictionary<string, object> result = this.parseWsTicker(ticker);
                result["timestamp"] = timestamp;
                result["datetime"] = datetime;
                string? symbol = ((string)(result != null && ((IDictionary<string, object>)result).ContainsKey("symbol") ? ((IDictionary<string, object>)result)["symbol"] : null));
                if ((symbol != null))
                {
                    this.tickers[(string)symbol] = result;
                }
                newTickers.Add(result);
                if ((channel != null))
                {
                    string messageHash = ((channel + "::") + symbol);
                    client.resolve(result, messageHash);
                    this.tryResolveUsdc(client, messageHash, result);
                }
            }
        }
    }

    public virtual Dictionary<string, object> parseWsTicker(object ticker, string? market = null)
    {
        //
        //     {
        //         "type": "ticker",
        //         "product_id": "DOGE-USD",
        //         "price": "0.08212",
        //         "volume_24_h": "242556423.3",
        //         "low_24_h": "0.07989",
        //         "high_24_h": "0.08308",
        //         "low_52_w": "0.04908",
        //         "high_52_w": "0.1801",
        //         "price_percent_chg_24_h": "0.50177456859626"
        // new as of 2024-04-12
        //         "best_bid":"0.07989",
        //         "best_bid_quantity": "500.0",
        //         "best_ask":"0.08308",
        //         "best_ask_quantity": "300.0"
        //     }
        //
        string? marketId = this.safeString(ticker, "product_id");
        object timestamp = null;
        double? last = this.safeNumber(ticker, "price");
        return this.safeTicker(new Dictionary<string, object>() {
            { "info", ticker },
            { "symbol", this.safeSymbol(marketId, market, "-") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", this.safeString(ticker, "high_24_h") },
            { "low", this.safeString(ticker, "low_24_h") },
            { "bid", this.safeString(ticker, "best_bid") },
            { "bidVolume", this.safeString(ticker, "best_bid_quantity") },
            { "ask", this.safeString(ticker, "best_ask") },
            { "askVolume", this.safeString(ticker, "best_ask_quantity") },
            { "vwap", null },
            { "open", null },
            { "close", last },
            { "last", last },
            { "previousClose", null },
            { "change", null },
            { "percentage", this.safeString(ticker, "price_percent_chg_24_h") },
            { "average", null },
            { "baseVolume", this.safeString(ticker, "volume_24_h") },
            { "quoteVolume", null },
        });
    }

